import { randomBytes } from 'crypto';
import { mkdirSync, readFileSync, rmSync } from 'fs';
import os from 'os';
import path from 'path';
import { z } from 'zod';
import { writeFileAtomicSync } from '../utils/writeFileAtomic';

const EDITOR_ACCESS_TOKEN_BYTES = 32;
const EditorSessionSchema = z.object({
  pid: z.number().int().positive(),
  port: z.number().int().positive(),
  projectPath: z.string(),
  startedAt: z.string(),
  token: z.string().regex(/^[A-Za-z0-9_-]{43}$/),
});

type EditorOwner = Omit<z.infer<typeof EditorSessionSchema>, 'token'>;

const editorSessionDirectory = (): string =>
  path.join(os.homedir(), '.rivet', 'editor-sessions');
const editorSessionPath = (owner: Pick<EditorOwner, 'pid' | 'port'>): string =>
  path.join(editorSessionDirectory(), `${owner.pid}-${owner.port}.json`);

export const createEditorAccessToken = (): string =>
  randomBytes(EDITOR_ACCESS_TOKEN_BYTES).toString('base64url');

export const writeEditorSession = (
  session: z.infer<typeof EditorSessionSchema>,
): void => {
  mkdirSync(editorSessionDirectory(), { recursive: true, mode: 0o700 });
  writeFileAtomicSync(
    editorSessionPath(session),
    JSON.stringify(EditorSessionSchema.parse(session)),
    { mode: 0o600 },
  );
};

export const readEditorAccessToken = (owner: EditorOwner): string | null => {
  try {
    const session = EditorSessionSchema.parse(
      JSON.parse(readFileSync(editorSessionPath(owner), 'utf8')),
    );
    return session.pid === owner.pid &&
      session.port === owner.port &&
      session.projectPath === owner.projectPath &&
      session.startedAt === owner.startedAt
      ? session.token
      : null;
  } catch {
    return null;
  }
};

export const removeEditorSession = (
  owner: EditorOwner,
  token: string,
): void => {
  if (readEditorAccessToken(owner) === token)
    rmSync(editorSessionPath(owner), { force: true });
};
